#define GRID_W 64
#define GRID_H 64
typedef struct { Entity *items[32]; int count; } Cell;
static Cell grid[GRID_H][GRID_W];

static void grid_insert(Entity *e) {
    Cell *c = &grid[e->y / CELL][e->x / CELL];
    c->items[c->count++] = e;
}
